SELECT 
FROM mail_forward_setting s
WHERE s.user_id = #{userId}

SELECT 
FROM mail_forward_rule f
WHERE f.mail_fwd_rule_idx = #{ruleIdx}
  AND f.user_id           = #{userId}

mapper.delete:
DELETE FROM mail_forward_rule
WHERE mail_fwd_rule_idx = #{ruleIdx}
  AND user_id           = #{userId}

mapper.select:
SELECT COUNT(*)
FROM mail_forward_rule f
WHERE f.user_id = #{userId}

SELECT COUNT(*)
FROM mail_forward_rule f
WHERE f.user_id    = #{userId}
  AND f.match_type = #{matchType}
  AND f.match_val  = LOWER(#{matchVal})

    AND f.mail_fwd_rule_idx != #{excludeIdx}

SELECT COALESCE(MAX(f.sort_order) + 1, 0)
FROM mail_forward_rule f
WHERE f.user_id = #{userId}
